"""Render subsystem handler.

Emits the C++ sources for the SDL2 renderer wrapper: window creation,
GPU/software backend selection, and the frame present loop. Template strings
are kept here rather than on disk so a generated project has zero external
template dependencies.
"""

from __future__ import annotations

from dataclasses import dataclass
from pathlib import Path

from src.core.engine_profile import EngineProfile

RENDER_HEADER = """\
#pragma once
// {name} — render subsystem. Generated by sdl2-game-engine-starter.
#include <SDL.h>
#include <cstdint>

namespace {ns}::render {{

enum class Backend : std::uint8_t {{ OpenGL, Vulkan, Software, D3D11 }};

struct FrameStats {{
    std::uint64_t frame_index;
    double        frame_ms;
}};

class Renderer {{
public:
    Renderer(SDL_Window* window, Backend backend);
    ~Renderer();

    Renderer(const Renderer&)            = delete;
    Renderer& operator=(const Renderer&) = delete;

    bool begin_frame() noexcept;
    void end_frame() noexcept;

    [[nodiscard]] const FrameStats& stats() const noexcept {{ return stats_; }}

private:
    SDL_Window*  window_;
    SDL_Renderer* sdl_renderer_;
    Backend      backend_;
    FrameStats   stats_{{}};
}};

}}  // namespace {ns}::render
"""

RENDER_SOURCE = """\
// {name} — render subsystem implementation.
#include "render/renderer.h"
#include <SDL.h>
#include <stdexcept>

namespace {ns}::render {{

static SDL_Renderer* make_sdl_renderer(SDL_Window* w, Backend b) {{
    Uint32 flags = 0;
    switch (b) {{
        case Backend::OpenGL:   flags = SDL_RENDERER_ACCELERATED | SDL_RENDERER_PRESENTVSYNC; break;
        case Backend::Vulkan:   flags = SDL_RENDERER_ACCELERATED; break;
        case Backend::Software: flags = SDL_RENDERER_SOFTWARE; break;
        case Backend::D3D11:    flags = SDL_RENDERER_ACCELERATED; break;
    }}
    SDL_Renderer* r = SDL_CreateRenderer(w, -1, flags);
    if (!r) throw std::runtime_error(SDL_GetError());
    return r;
}}

Renderer::Renderer(SDL_Window* window, Backend backend)
    : window_(window), sdl_renderer_(make_sdl_renderer(window, backend)), backend_(backend) {{}}

Renderer::~Renderer() {{ if (sdl_renderer_) SDL_DestroyRenderer(sdl_renderer_); }}

bool Renderer::begin_frame() noexcept {{
    SDL_SetRenderDrawColor(sdl_renderer_, 12, 12, 16, 255);
    SDL_RenderClear(sdl_renderer_);
    return true;
}}

void Renderer::end_frame() noexcept {{
    SDL_RenderPresent(sdl_renderer_);
    stats_.frame_index += 1;
}}

}}  // namespace {ns}::render
"""


@dataclass(slots=True)
class RenderHandler:
    profile: EngineProfile

    @property
    def namespace(self) -> str:
        return self.profile.name.replace("-", "_").lower()

    def emit(self, project_root: Path) -> list[Path]:
        out_dir = project_root / "src" / "engine_cpp" / "render"
        out_dir.mkdir(parents=True, exist_ok=True)
        ns = self.namespace
        header = out_dir / "renderer.h"
        source = out_dir / "renderer.cpp"
        header.write_text(
            RENDER_HEADER.format(name=self.profile.name, ns=ns), encoding="utf-8"
        )
        source.write_text(
            RENDER_SOURCE.format(name=self.profile.name, ns=ns), encoding="utf-8"
        )
        return [header, source]